   "summary": "DoS（阻斷服務）攻擊的目的不是偷資料，而是把目標的頻寬、連線數、CPU 等資源耗盡，讓正常使用者連不上服務，破壞的是「可用性」。就像一群人故意堵在小店門口假裝排隊，真正的客人進不來。如果攻擊來自大量被控制的電腦（殭屍網路）同時發動，就叫 DDoS（分散式阻斷服務）。指引把 DDoS 分成基礎設施層（第 3、4 層，例如 SYN Flood、UDP Flood）與應用層（第 6、7 層，例如 HTTP Flood）。防禦上，指引建議用防火牆限制同一來源 IP 的連線數；實務上也會搭配 CDN、流量清洗。考試常考：定義與目的、攻擊屬於哪一層、最有效的防護措施。",
