   "summary": "防火牆是放在網路邊界（通常在網際網路與企業內網之間）的過濾關卡，依規則決定哪些封包可以進出，是首要的防衛機制。指引把類型分成過濾型（網路層的封包過濾、應用層防火牆）與代理型（Proxy）。封包過濾只看 IP 標頭的來源／目的位址、埠號、協定，規則由管理者逐條設定；狀態檢視防火牆會用「狀態表」記住連線，看的內容比單純封包過濾多；應用層（代理）防火牆在第 7 層檢查內容，代理會替內部主機另開新連線，更難讓駭客從外部竄改內部系統。新一代防火牆（NGFW）再整合 VPN、DLP、IPS、沙箱等功能。考試常考各類型的運作層級與看得到的內容。",
