   "summary": "雜湊函數把任意長度的資料算成固定長度的「指紋」，資料只要改一個字，指紋就完全不同，而且無法從指紋倒推原文，常用來驗證資料完整性。MD5、SHA-1 已被證實存在碰撞攻擊（能找出兩份不同資料算出相同雜湊），不應再用於完整性驗證或數位簽章，建議使用 SHA-256 以上。單純的雜湊沒有金鑰，攻擊者改了資料可以重算雜湊；另外，用 SHA-256 等 Merkle–Damgård 結構做的 H(密鑰‖訊息) 還可能遭長度延展攻擊，這時要用 HMAC（雜湊搭配金鑰的雙層結構）才能同時驗證完整性與來源。指引提到數位簽章可提供不可否認性與訊息完整性。",
