   "summary": "對稱式加密用同一把金鑰加解密（如 AES、DES），速度快，適合加密大量資料，缺點是金鑰要怎麼安全地交給對方。非對稱式加密有一對金鑰：公鑰加密、私鑰解密（或私鑰簽章、公鑰驗證），如 RSA、ECC，不必事先共享秘密，但運算較慢。實務上採混合式架構：先用非對稱加密（或金鑰交換）安全地交換一把對稱金鑰，再用對稱金鑰加密大量資料，TLS 就是這樣運作。對稱加密還有「工作模式」：ECB 相同明文會產生相同密文，不建議使用；CBC 只加密，需另外做完整性；GCM（伽羅瓦／計數器模式）同時提供加密與完整性驗證。DES 是演算法，不是工作模式。指引未涵蓋，依歷屆考題整理。",
