   "summary": "通訊安全的目標，是保持資訊在組織內部或與外部組織往來時的安全。指引的控制措施包括：保護傳送的資訊不被截取、複製、修改、破壞；機密或敏感個資透過網際網路傳輸時，必須使用加密等安全機制；並建立資訊轉移的政策、程序與控制。回到資安三要素：機密性（只有授權者能看）、完整性（資料在傳輸過程中未被未經授權的修改）、可用性（需要時可隨時使用）。端對端加密（E2EE）指資料從發送端出發就加密，一直到接收端才解密，中途的伺服器與網路業者都看不到明文，所以資料在傳輸過程中始終處於加密狀態，只有通訊的兩端能解密。",
