   "summary": "後門（Backdoor）是繞過正常安全控管、用隱密管道取得存取權的方法，有兩種來源：一是開發者為了日後維護、除錯留下的管理後門，若被駭客發現並利用，就變成入侵入口；二是惡意植入（夾帶在郵件或軟體中），可能偷密碼、遠端控制主機、監看螢幕與鍵盤。持久化（Persistence）則是駭客入侵成功後，確保重開機後還能繼續執行，例如把惡意程式加進 Windows 登錄檔的 Run／RunOnce、排程工作、啟動資料夾、服務，或建立隱藏帳號。防禦：上線前移除維護用後門與除錯碼、監控啟動項目與排程變化、定期稽核帳號。",
