   "summary": "特權提升（Privilege Escalation，提權）是攻擊者入侵一般帳號後，設法把權限拉高到管理員等級（Windows 的 Administrator／SYSTEM、Linux 的 root），以取得更完整的控制。分垂直提權（普通使用者升成管理員）與水平提權（換成同級別其他人的身分）。常見手法：利用作業系統或服務漏洞（如 Linux 的 Dirty COW）、錯誤的權限設定（如 SetUID 程式）、Windows 的 Potato 系列（如 Juicy Potato），也會翻找系統中高權限帳號的密碼或破解雜湊。注意 Chisel 是隧道（Tunneling）工具，用來穿越網路，不是提權技巧。防禦：最小權限、及時修補、UAC。",
