   "summary": "勒索軟體（Ransomware）會把受害者的電腦鎖住，或把硬碟上的檔案加密，再要求贖金才肯給解鎖或解密金鑰；它可能以病毒、蠕蟲或木馬的形式出現，常透過釣魚信件、惡意附件、漏洞散播。就算付錢也不保證拿回資料，所以最重要的防線是備份：定期備份重要資料，並放在離線或與主系統隔離的地方。其他措施：更新修補程式、端點防護與病毒碼更新、員工防釣魚訓練加 MFA、網路分區隔離（限制擴散範圍）。注意：若備份與主機持續自動同步，檔案被加密後雲端副本可能一起被覆蓋，所以「全部放雲端」不等於安全。",
