   "summary": "資料庫集中存放最有價值的資料，因此是攻擊者的首要目標。常見威脅：資料外洩、資料遭非法竄改或偽造、SQL 注入、權限過大或帳號被冒用、備份外流，以及「資料庫推論（Database Inference）」——攻擊者不直接讀取機密，而是把多筆合法可查的低敏感資料（例如統計值）拼湊推論出機密內容。防護做法：用多因素驗證與最小權限確保存取身分、敏感資料加密、定期更新與修補資料庫軟體、監控資料庫活動並保留稽核紀錄；不能因為資料庫在內網就不監控。至於資料庫管理人員有沒有作業系統操作認證，只是人員資格，不是技術上的安全威脅。指引未涵蓋，依歷屆考題整理。",
