   "summary": "Windows 程式啟動時會去載入需要的 DLL（動態連結程式庫），並依固定的搜尋順序找檔案（通常先找程式自己所在的資料夾）。DLL 側載（Sideloading）就是攻擊者把惡意 DLL 取成合法程式要載入的名稱，放在搜尋順序較前面的位置（常與一個合法、有簽章的程式放在一起），程式一執行就載入並執行惡意 DLL。因為宿主程式是正常且受信任的，常能躲過防毒軟體。相關概念還有 DLL 劫持（Hijacking）、DLL 注入。防禦：以完整路徑載入 DLL、驗證 DLL 數位簽章、限制程式資料夾的寫入權限、使用應用程式白名單。指引未涵蓋，依歷屆考題整理。",
