   "summary": "軟體開發生命週期（SDLC）包含需求、設計、實作、測試、部署與維運。「安全左移」的精神是安全要在開發初期（需求與設計階段）就納入，而不是最後才補，因為越晚修越貴，在維運階段修正同一個安全問題的成本最高。相關框架：ISO/IEC 27034（開發軟體安全的流程與框架國際標準）、Microsoft SDL（訓練、要求、設計、實施、驗證、發行，發行要有事件回應計畫）、Cigital 的 SSDLC（需求定義、設計、部署等，沒有「報告」這個階段）。DevSecOps 是 DevOps 的延伸，把安全整合進每個階段，文化涵蓋開發（Dev）、安全（Sec）、營運（Ops），名稱中不含「規劃」。",
