     "explanation": "答案 (C)。使用鹽（Salt）加 SHA-2 雜湊，既不可逆又能抵抗彩虹表，是這幾項中最適當的做法。A 錯：存放在設定檔等於暴露；B 錯：SHA-1 已不夠安全，且沒加鹽；D 錯：直接儲存等於明文。",
