   "summary": "修補程式（Patch）是廠商針對已知漏洞發布的修正，定期更新與修補是降低資安風險、維持系統穩定最有效的做法。指引提醒：安裝前要先測試並評估，確認有效且不會造成無法容忍的副作用；管理上要先有完整資產清冊，才知道哪些系統需要修補。實務上更新來源要可信，可用雜湊值驗證完整性，先在測試機升級，更新後同步更新軟體物料清單（SBOM）。收到『請立即升級』的信件不能直接點，可能是釣魚。若暫時無法修補，要改用關閉服務、增加其他控制措施、加強監控等方式補強。",
