   "summary": "RPO（復原點目標）是『最多能容忍丟失多久的資料』，決定備份的頻率：備份間隔不能大於 RPO，例如 RPO 4 小時，至少每 4 小時備份一次。RTO（復原時間目標）是『服務中斷後最多能多久恢復』，決定要用哪種備援方式。MTPD（最大可容忍中斷時間）是業務可承受的中斷上限，RTO 必須小於它。備援依準備程度分：熱備援（持續同步、隨時待命，秒到分鐘級切換、資料幾乎零遺失）、溫備援、冷備援（只有場地與基本設備，恢復最慢），越快成本越高。指引未涵蓋，依歷屆考題整理。",
